import java.io.*;
import java.util.*;

public class Main {
    private static final InputStream IN = System.in;
    private static final byte[] BUF = new byte[1 << 16];
    private static int len = 0, ptr = 0;

    private static int read() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    private static int skipSpaces() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        return c;
    }

    private static String next() throws IOException {
        int c = skipSpaces();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    private static long nextLong() throws IOException {
        int c = skipSpaces();
        boolean negative = c == '-';
        if (negative) c = read();
        long value = 0;
        while (c >= '0' && c <= '9') {
            value = value * 10 + (c - '0');
            c = read();
        }
        return negative ? -value : value;
    }

    public static void main(String[] args) throws IOException {
        String s = next(), kit = next();
        long balance = 0, low = 0;
        for (int i = 0; i < s.length(); i++) {
            balance += s.charAt(i) == '(' ? 1 : -1;
            low = Math.min(low, balance);
        }
        // Opens and closes that must be added; any extra ones come in pairs.
        int left = (int) -low, right = (int) (left + balance);
        int openCount = 0;
        for (int i = 0; i < kit.length(); i++) if (kit.charAt(i) == '(') openCount++;
        long[] opens = new long[openCount], closes = new long[kit.length() - openCount];
        for (int i = 0, o = 0, c = 0; i < kit.length(); i++) {
            long v = nextLong();
            if (kit.charAt(i) == '(') opens[o++] = v;
            else closes[c++] = v;
        }
        // Sorted ascending; walk from the end to take the highest ratings first.
        Arrays.sort(opens);
        Arrays.sort(closes);
        long answer = 0;
        for (int i = 0; i < Math.min(left, opens.length); i++) answer += opens[opens.length - 1 - i];
        for (int i = 0; i < Math.min(right, closes.length); i++) answer += closes[closes.length - 1 - i];
        for (int i = left, j = right; i < opens.length && j < closes.length; i++, j++) {
            long gain = opens[opens.length - 1 - i] + closes[closes.length - 1 - j];
            if (gain <= 0) break;
            answer += gain;
        }
        System.out.println(answer);
    }
}

package main

import (
	"io"
	"os"
	"slices"
	"strconv"
)

var data []byte
var pos int

// next returns the next whitespace-separated token of the input.
func next() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	token := next()
	negative := len(token) > 0 && token[0] == '-'
	if negative {
		token = token[1:]
	}
	value := 0
	for _, c := range token {
		value = value*10 + int(c-'0')
	}
	if negative {
		return -value
	}
	return value
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	s, kit := string(next()), string(next())
	balance, low := 0, 0
	for _, c := range s {
		if c == '(' {
			balance++
		} else {
			balance--
		}
		low = min(low, balance)
	}
	// Opens and closes that must be added; any extra ones come in pairs.
	left, right := -low, -low+balance
	var opens, closes []int
	for _, c := range kit {
		v := nextInt()
		if c == '(' {
			opens = append(opens, v)
		} else {
			closes = append(closes, v)
		}
	}
	descending := func(a, b int) int { return b - a }
	slices.SortFunc(opens, descending)
	slices.SortFunc(closes, descending)
	answer := 0
	for i := 0; i < min(left, len(opens)); i++ {
		answer += opens[i]
	}
	for i := 0; i < min(right, len(closes)); i++ {
		answer += closes[i]
	}
	for i, j := left, right; i < len(opens) && j < len(closes); i, j = i+1, j+1 {
		if opens[i]+closes[j] <= 0 {
			break
		}
		answer += opens[i] + closes[j]
	}
	os.Stdout.WriteString(strconv.Itoa(answer) + "\n")
}
